local DrawbridgeMaker = {}
local PRODUCTS = {
    simple_wood_drawbridge = { name = "Preprost lesen dvižni most", woodCost = 5, ironCost = 2, ropeCost = 2, time = 7, cost = 280, defense = 28, happiness = 1, description = "Preprost lesen dvižni most za jarek." },
    iron_reinforced_drawbridge = { name = "Železnookrepljen dvižni most", woodCost = 4, ironCost = 3, steelCost = 1, ropeCost = 2, time = 10, cost = 620, defense = 42, happiness = 2, prestige = 3, description = "Železnookrepljen dvižni most za trgovce." },
    silver_chain_drawbridge = { name = "Srebrnoverižni dvižni most", woodCost = 4, ironCost = 2, silverCost = 2, steelCost = 1, ropeCost = 2, time = 14, cost = 1400, defense = 58, happiness = 2, prestige = 8, description = "Srebrnoverižni dvižni most za plemiče." },
    gold_trimmed_drawbridge = { name = "Zlatookrasni dvižni most", woodCost = 4, ironCost = 2, goldCost = 2, silverCost = 1, steelCost = 1, ropeCost = 2, time = 18, cost = 3200, defense = 72, happiness = 3, prestige = 18, description = "Zlatookrasni dvižni most za visoke plemiče." },
    jewel_pinned_drawbridge = { name = "Draguljnoprity dvižni most", woodCost = 4, ironCost = 2, goldCost = 2, silverCost = 1, steelCost = 1, ropeCost = 2, jewelCost = 1, time = 22, cost = 6800, defense = 85, happiness = 5, prestige = 32, description = "Dvižni most z draguljno priponko za visoko plemstvo." },
    royal_grand_drawbridge = { name = "Kraljevski veliki dvižni most", woodCost = 6, ironCost = 3, goldCost = 3, silverCost = 2, steelCost = 2, ropeCost = 2, jewelCost = 2, pearlCost = 2, time = 29, cost = 14000, defense = 98, happiness = 13, prestige = 65, description = "Veliki kraljevski dvižni most z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    drawbridge_workshop = { name = "Mostna delavnica", cost = { gold = 320, wood = 180, stone = 140, iron = 6, rope = 6 }, upkeep = 7, qualityBonus = 5 },
    bridge_loft = { name = "Mostna podstrešje", cost = { gold = 1100, wood = 320, stone = 320, steel = 6, silver = 6 }, upkeep = 26, qualityBonus = 18 },
    master_bridge_atelier = { name = "Mojstrski mostni atelje", cost = { gold = 2900, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 68, qualityBonus = 30 },
    royal_bridge_palace = { name = "Kraljevska mostna palača", cost = { gold = 12500, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 250, qualityBonus = 55, prestigeBonus = 50 },
}
DrawbridgeMaker.woodStock = 22; DrawbridgeMaker.ironStock = 14; DrawbridgeMaker.steelStock = 8; DrawbridgeMaker.ropeStock = 12; DrawbridgeMaker.silverStock = 6; DrawbridgeMaker.goldStock = 6; DrawbridgeMaker.jewelStock = 4; DrawbridgeMaker.pearlStock = 4
DrawbridgeMaker.productStock = {}; DrawbridgeMaker.buildings = {}; DrawbridgeMaker.maker = nil; DrawbridgeMaker.activeMaking = {}; DrawbridgeMaker.totalProducts = 0; DrawbridgeMaker.dayTimer = 0
function DrawbridgeMaker.init() DrawbridgeMaker.woodStock=22; DrawbridgeMaker.ironStock=14; DrawbridgeMaker.steelStock=8; DrawbridgeMaker.ropeStock=12; DrawbridgeMaker.silverStock=6; DrawbridgeMaker.goldStock=6; DrawbridgeMaker.jewelStock=4; DrawbridgeMaker.pearlStock=4; DrawbridgeMaker.productStock={}; DrawbridgeMaker.buildings={}; DrawbridgeMaker.maker=nil; DrawbridgeMaker.activeMaking={}; DrawbridgeMaker.totalProducts=0; DrawbridgeMaker.dayTimer=0; print("[DrawbridgeMaker] Royal Drawbridge Maker System initialized (6 products, 4 buildings)") end
function DrawbridgeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=600+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; DrawbridgeMaker.maker={name=n or ("Mostar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mostar najet: %s (spretnost: %d)",DrawbridgeMaker.maker.name,s),"success") end; return true end
function DrawbridgeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function DrawbridgeMaker.build(id) local ok,e=DrawbridgeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(DrawbridgeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function DrawbridgeMaker.getQualityBonus() local b=0; for _,bd in ipairs(DrawbridgeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function DrawbridgeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and DrawbridgeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and DrawbridgeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and DrawbridgeMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.ropeCost and DrawbridgeMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.silverCost and DrawbridgeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and DrawbridgeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and DrawbridgeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and DrawbridgeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #DrawbridgeMaker.buildings==0 then return false,"Potrebna mostna delavnica" end; if not DrawbridgeMaker.maker then return false,"Potreben mostar" end; return true end
function DrawbridgeMaker.make(pt,qty) qty=qty or 1; local ok,e=DrawbridgeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then DrawbridgeMaker.woodStock=DrawbridgeMaker.woodStock-d.woodCost*qty end; if d.ironCost then DrawbridgeMaker.ironStock=DrawbridgeMaker.ironStock-d.ironCost*qty end; if d.steelCost then DrawbridgeMaker.steelStock=DrawbridgeMaker.steelStock-d.steelCost*qty end; if d.ropeCost then DrawbridgeMaker.ropeStock=DrawbridgeMaker.ropeStock-d.ropeCost*qty end; if d.silverCost then DrawbridgeMaker.silverStock=DrawbridgeMaker.silverStock-d.silverCost*qty end; if d.goldCost then DrawbridgeMaker.goldStock=DrawbridgeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then DrawbridgeMaker.jewelStock=DrawbridgeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then DrawbridgeMaker.pearlStock=DrawbridgeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if DrawbridgeMaker.maker then t=math.max(1,t-math.floor(DrawbridgeMaker.maker.skill/12)) end; table.insert(DrawbridgeMaker.activeMaking,{id="drawbridge_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,defense=d.defense or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function DrawbridgeMaker.completeMaking(m) local q=1.0+(DrawbridgeMaker.getQualityBonus()/100); if DrawbridgeMaker.maker then q=q+(DrawbridgeMaker.maker.skill/140) end; q=math.min(2.5,q); DrawbridgeMaker.productStock[m.productType]=(DrawbridgeMaker.productStock[m.productType] or 0)+m.quantity; DrawbridgeMaker.totalProducts=DrawbridgeMaker.totalProducts+m.quantity; if m.defense>0 and _G.state then _G.state.defense=(_G.state.defense or 0)+m.defense end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if DrawbridgeMaker.maker then DrawbridgeMaker.maker.itemsMade=DrawbridgeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then DrawbridgeMaker.maker.skill=math.min(100,DrawbridgeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dvižni most izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"drawbridge.completed",{productName=m.productName,defense=m.defense,prestige=m.prestige,happiness=m.happiness}) end end
function DrawbridgeMaker.update(dt) if not _G.state then return end; DrawbridgeMaker.dayTimer=DrawbridgeMaker.dayTimer+dt; if DrawbridgeMaker.dayTimer>=30 then DrawbridgeMaker.dayTimer=0; for i=#DrawbridgeMaker.activeMaking,1,-1 do local m=DrawbridgeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then DrawbridgeMaker.completeMaking(m); table.remove(DrawbridgeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(DrawbridgeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if DrawbridgeMaker.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function DrawbridgeMaker.getStats() return {woodStock=DrawbridgeMaker.woodStock,ironStock=DrawbridgeMaker.ironStock,steelStock=DrawbridgeMaker.steelStock,ropeStock=DrawbridgeMaker.ropeStock,silverStock=DrawbridgeMaker.silverStock,goldStock=DrawbridgeMaker.goldStock,jewelStock=DrawbridgeMaker.jewelStock,pearlStock=DrawbridgeMaker.pearlStock,productStock=DrawbridgeMaker.productStock,numBuildings=#DrawbridgeMaker.buildings,hasMaker=DrawbridgeMaker.maker~=nil,makerName=DrawbridgeMaker.maker and DrawbridgeMaker.maker.name or "—",makerSkill=DrawbridgeMaker.maker and DrawbridgeMaker.maker.skill or 0,activeMaking=#DrawbridgeMaker.activeMaking,totalProducts=DrawbridgeMaker.totalProducts} end
return DrawbridgeMaker
